-- =====================================================================
-- THE WORKER — שער 10, פרה עיוורת: הדו-קרב (24.9.2026)
-- =====================================================================
--
-- **קובץ עצמאי.** לא תלוי בשני הקבצים של 22.9 ולא נוגע בהם. מריצים אותו אחריהם.
-- **אם מריצים שוב את 20260922120000_worker_collector_market.sql — מריצים אחריו גם את זה**:
-- הקובץ ההוא סוגר בסוף את ההרשאה לכל פונקציית worker_ שהוא לא מכיר, כולל אלה.
--
-- מה זה: מפרט Gate 10 §6–§10. שני אנשים מקבלים אותו שחקן, אותם עשרה רמזים באותו סדר ואותה
-- גרסת ניקוד. המסד הוא השופט:
--
--   · **התשובה והרמזים שלא נפתחו לא יוצאים מכאן.** `worker_blind_cow_question` מחזיקה את
--     עשרת הרמזים ואת מזהה השחקן של כל שאלת דו-קרב, ואין לה grant לאף אחד. רמז יוצא רק
--     כשפותחים אותו, והתשובה רק כשהריצה של השואל נגמרה.
--   · **הזמן הוא של השרת.** started_at / finished_at הם now() של המסד. הזמן של הדפדפן לא
--     נכנס לחישוב (`client_elapsed_ms` נשמר לאבחון בלבד).
--   · **התוצאה של הצד הראשון מוסתרת** מהצד השני עד שהוא עצמו סיים (מפרט §10).
--   · **אין קריאה ישירה מהטבלאות.** RLS דלוק, אין policy ואין grant. כל פעולה היא פונקציית
--     `security definer` שמחזירה `{ ok }` או `{ ok:false, error }` כערך — לא כשגיאה.
--   · **זהות בלי חשבון.** הדו-קרב פתוח גם לאורחים (מפרט §12): השרת של THE WORKER מחזיק
--     לכל מכשיר מפתח אקראי בעוגייה httpOnly ושולח אותו כאן; נשמר רק ה-sha256 שלו. אותו
--     מפתח לא יכול לשבת בשני המקומות של אותו דו-קרב (unique על duel_id, anon_id).
--   · **הטוקן בלינק אינו מזהה רץ**: 32 תווים אקראיים (gen_random_uuid), ונשמר רק ה-hash.
--     פג אחרי 7 ימים. שאלה שהבנק החליף ממשיכה בדו-קרב על הגרסה שבה נוצר.
--
-- **הפרויקט משותף עם DUBID** (כלל 89): כל אובייקט מתחיל ב-worker_, אין שום דבר על auth.
-- **הרצה חוזרת בטוחה**, ונבדקה פעמיים ברצף על Postgres 16 מקומי עם auth מדומה
-- (`scripts/db/verify.sh`, `supabase/tests/30-blind-cow.sql`).
--
-- **בסוף הקובץ יש שאילתת בדיקה.** התוצאה הנכונה:
--   `blind_cow_tables 6 · blind_cow_functions 15 · duel_questions 216 · anon_can_write 0 · auth_triggers 0`

-- =====================================================================
-- 1. הבנק — שאלות הדו-קרב (נוצר מ-content/generated/blind-cow-bank.json)
-- =====================================================================
create table if not exists public.worker_blind_cow_question (
  question_id      text not null check (question_id ~ '^bq_[0-9a-f]{12}$'),
  version          integer not null check (version >= 1),
  target_player_id text not null check (target_player_id ~ '^p_[0-9a-f]{10}$'),
  -- [{ n, labelHe, valueHe, type }] × 10, בסדר שבו הם נפתחים
  clues            jsonb not null check (jsonb_typeof(clues) = 'array' and jsonb_array_length(clues) = 10),
  bank_version     integer not null,
  created_at       timestamptz not null default now(),
  primary key (question_id, version)
);
create index if not exists worker_blind_cow_question_bank_idx on public.worker_blind_cow_question (bank_version);

-- גרסאות הניקוד (מפרט §6.2): 15 שניות לרמז נוסף, 5 לניחוש שגוי, 120 שניות לריצת דו-קרב.
create table if not exists public.worker_blind_cow_scoring (
  version                integer primary key,
  extra_hint_penalty_ms  integer not null check (extra_hint_penalty_ms >= 0),
  wrong_guess_penalty_ms integer not null check (wrong_guess_penalty_ms >= 0),
  duel_max_ms            integer not null check (duel_max_ms > 0)
);
insert into public.worker_blind_cow_scoring (version, extra_hint_penalty_ms, wrong_guess_penalty_ms, duel_max_ms)
values (1, 15000, 5000, 120000)
on conflict (version) do nothing;

-- =====================================================================
-- 2. הדו-קרב, שני המקומות, הריצות והיומן (מפרט §7)
-- =====================================================================
create table if not exists public.worker_blind_cow_duel (
  id                 uuid primary key default gen_random_uuid(),
  public_token_hash  text not null unique,
  question_id        text not null,
  question_version   integer not null,
  scoring_version    integer not null references public.worker_blind_cow_scoring(version),
  status             text not null default 'waiting' check (status in ('waiting', 'active', 'completed', 'expired')),
  created_by_user_id uuid,
  created_by_anon_id text,
  created_at         timestamptz not null default now(),
  expires_at         timestamptz not null default now() + interval '7 days',
  completed_at       timestamptz,
  foreign key (question_id, question_version) references public.worker_blind_cow_question(question_id, version)
);
create index if not exists worker_blind_cow_duel_creator_idx on public.worker_blind_cow_duel (created_by_anon_id, created_at desc);

create table if not exists public.worker_blind_cow_run (
  id                uuid primary key default gen_random_uuid(),
  mode              text not null check (mode in ('solo', 'daily', 'duel')),
  duel_id           uuid references public.worker_blind_cow_duel(id) on delete cascade,
  question_id       text not null,
  question_version  integer not null,
  user_id           uuid,
  anon_id           text,
  started_at        timestamptz not null default now(),
  finished_at       timestamptz,
  status            text not null default 'playing' check (status in ('playing', 'solved', 'gave_up', 'timeout')),
  hints_used        integer not null default 1 check (hints_used between 1 and 10),
  wrong_guesses     integer not null default 0 check (wrong_guesses >= 0),
  raw_elapsed_ms    bigint,
  weighted_time_ms  bigint,
  result_player_id  text,
  scoring_version   integer not null references public.worker_blind_cow_scoring(version),
  client_elapsed_ms bigint
);
create index if not exists worker_blind_cow_run_duel_idx on public.worker_blind_cow_run (duel_id);

create table if not exists public.worker_blind_cow_duel_slot (
  id           uuid primary key default gen_random_uuid(),
  duel_id      uuid not null references public.worker_blind_cow_duel(id) on delete cascade,
  slot         smallint not null check (slot in (1, 2)),
  user_id      uuid,
  anon_id      text,
  display_name text check (display_name is null or char_length(display_name) <= 24),
  joined_at    timestamptz,
  run_id       uuid references public.worker_blind_cow_run(id),
  unique (duel_id, slot),
  -- אותו מכשיר לא יושב בשני הצדדים של אותו דו-קרב (מפרט §10)
  unique (duel_id, anon_id)
);

create table if not exists public.worker_blind_cow_run_event (
  id        bigint generated always as identity primary key,
  run_id    uuid not null references public.worker_blind_cow_run(id) on delete cascade,
  kind      text not null check (kind in ('START', 'REVEAL_HINT', 'OPEN_GUESS', 'SUBMIT_WRONG', 'SUBMIT_CORRECT', 'GIVE_UP', 'TIMEOUT')),
  hint      integer,
  player_id text check (player_id is null or player_id ~ '^p_[0-9a-f]{10}$'),
  at        timestamptz not null default now()
);
create index if not exists worker_blind_cow_run_event_run_idx on public.worker_blind_cow_run_event (run_id, id);

-- =====================================================================
-- 3. עזרים פנימיים — אף אחד מבחוץ לא קורא להם
-- =====================================================================
create or replace function public.worker_blind_cow_fail(p_error text) returns jsonb
language sql immutable as $$ select jsonb_build_object('ok', false, 'error', p_error) $$;

/* המפתח של המכשיר → המזהה שנשמר. null למפתח שאינו 32–64 תווי hex. */
create or replace function public.worker_blind_cow_me(p_me text) returns text
language sql immutable as $$
  select case when p_me ~ '^[0-9a-f]{32,64}$'
    then encode(sha256(convert_to('worker-blind-cow|' || p_me, 'UTF8')), 'hex') end
$$;

create or replace function public.worker_blind_cow_token_hash(p_token text) returns text
language sql immutable as $$
  select case when p_token ~ '^[0-9a-f]{32}$'
    then encode(sha256(convert_to('worker-blind-cow-duel|' || p_token, 'UTF8')), 'hex') end
$$;

/* זמן משוקלל (מפרט §6.2) — אותה נוסחה כמו lib/game/blind-cow/scoring.ts. */
create or replace function public.worker_blind_cow_weighted(p_raw bigint, p_hints integer, p_wrong integer, p_version integer)
returns bigint
language sql stable security definer set search_path = public as $$
  select greatest(p_raw, 0)
       + (greatest(p_hints, 1) - 1)::bigint * s.extra_hint_penalty_ms
       + greatest(p_wrong, 0)::bigint * s.wrong_guess_penalty_ms
    from public.worker_blind_cow_scoring s where s.version = p_version
$$;

/* סוגר ריצת דו-קרב שעברה את מגבלת הזמן. הזמן נחתך בדיוק במגבלה, לא ברגע שמישהו שאל. */
create or replace function public.worker_blind_cow_settle(p_run uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_run public.worker_blind_cow_run; v_max integer;
begin
  select * into v_run from public.worker_blind_cow_run where id = p_run for update;
  if not found or v_run.status <> 'playing' or v_run.mode <> 'duel' then return; end if;
  select duel_max_ms into v_max from public.worker_blind_cow_scoring where version = v_run.scoring_version;
  if now() > v_run.started_at + make_interval(secs => v_max / 1000.0) then
    update public.worker_blind_cow_run
       set status = 'timeout', finished_at = v_run.started_at + make_interval(secs => v_max / 1000.0),
           raw_elapsed_ms = v_max
     where id = p_run;
    insert into public.worker_blind_cow_run_event (run_id, kind) values (p_run, 'TIMEOUT');
  end if;
end $$;

/* הדו-קרב נסגר כששתי הריצות נגמרו. */
create or replace function public.worker_blind_cow_close(p_duel uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.worker_blind_cow_duel d set status = 'completed', completed_at = now()
   where d.id = p_duel and d.status <> 'completed'
     and (select count(*) from public.worker_blind_cow_duel_slot s
            join public.worker_blind_cow_run r on r.id = s.run_id
           where s.duel_id = p_duel and r.status <> 'playing') = 2;
end $$;

/* הריצה כפי שבעליה רואה אותה: הרמזים שנפתחו, ורק אחרי הסיום — התשובה והכול. */
create or replace function public.worker_blind_cow_view(p_run uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_run public.worker_blind_cow_run; v_q public.worker_blind_cow_question; v_done boolean;
begin
  select * into v_run from public.worker_blind_cow_run where id = p_run;
  if not found then return null; end if;
  select * into v_q from public.worker_blind_cow_question where question_id = v_run.question_id and version = v_run.question_version;
  v_done := v_run.status <> 'playing';
  return jsonb_build_object(
    'status', v_run.status,
    'startedAt', (extract(epoch from v_run.started_at) * 1000)::bigint,
    'finishedAt', case when v_done then (extract(epoch from v_run.finished_at) * 1000)::bigint end,
    'serverNow', (extract(epoch from now()) * 1000)::bigint,
    'hintsUsed', v_run.hints_used,
    'wrongGuesses', v_run.wrong_guesses,
    'total', jsonb_array_length(v_q.clues),
    'clues', (select coalesce(jsonb_agg(c order by (c ->> 'n')::int), '[]'::jsonb)
                from jsonb_array_elements(v_q.clues) c
               where v_done or (c ->> 'n')::int <= v_run.hints_used),
    'tried', (select coalesce(jsonb_agg(distinct e.player_id), '[]'::jsonb)
                from public.worker_blind_cow_run_event e where e.run_id = p_run and e.kind = 'SUBMIT_WRONG'),
    'rawElapsedMs', case when v_done then v_run.raw_elapsed_ms end,
    'weightedTimeMs', case when v_done then v_run.weighted_time_ms end,
    'scoringVersion', v_run.scoring_version,
    'answer', case when v_done then v_q.target_player_id end
  );
end $$;

/* המקום של השואל בדו-קרב (אחרי בדיקת טוקן ותוקף), או null. */
create or replace function public.worker_blind_cow_my_slot(p_me text, p_token text)
returns public.worker_blind_cow_duel_slot
language sql stable security definer set search_path = public as $$
  select s.* from public.worker_blind_cow_duel d
    join public.worker_blind_cow_duel_slot s on s.duel_id = d.id
   where d.public_token_hash = public.worker_blind_cow_token_hash(p_token)
     and s.anon_id = public.worker_blind_cow_me(p_me)
$$;

-- =====================================================================
-- 4. הפעולות — שבע, כולן מחזירות ערך
-- =====================================================================

/* יצירת דו-קרב: שאלה אקראית מהבנק העדכני, הטוקן חוזר פעם אחת ולא נשמר. */
create or replace function public.worker_blind_cow_duel_create(p_me text, p_name text default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_me text := public.worker_blind_cow_me(p_me);
  v_token text := replace(gen_random_uuid()::text, '-', '');
  v_q public.worker_blind_cow_question;
  v_duel uuid;
begin
  if v_me is null then return public.worker_blind_cow_fail('bad_identity'); end if;
  -- מכסה: 30 דו-קרבות בשעה למכשיר. השורות עצמן הן המונה, ולכן הוא לא מתבטל בכישלון.
  if (select count(*) from public.worker_blind_cow_duel
       where created_by_anon_id = v_me and created_at > now() - interval '1 hour') >= 30 then
    return public.worker_blind_cow_fail('slow_down');
  end if;
  select * into v_q from public.worker_blind_cow_question
   where bank_version = (select max(bank_version) from public.worker_blind_cow_question)
   order by random() limit 1;
  if not found then return public.worker_blind_cow_fail('no_questions'); end if;
  insert into public.worker_blind_cow_duel (public_token_hash, question_id, question_version, scoring_version,
                                            created_by_user_id, created_by_anon_id)
  values (public.worker_blind_cow_token_hash(v_token), v_q.question_id, v_q.version,
          (select max(version) from public.worker_blind_cow_scoring), auth.uid(), v_me)
  returning id into v_duel;
  insert into public.worker_blind_cow_duel_slot (duel_id, slot, user_id, anon_id, display_name, joined_at)
  values (v_duel, 1, auth.uid(), v_me, nullif(left(btrim(coalesce(p_name, '')), 24), ''), now());
  return jsonb_build_object('ok', true, 'token', v_token, 'slot', 1);
end $$;

/* הצטרפות בלינק. מי שכבר בפנים מקבל את המקום שלו בחזרה; מקום שלישי אין. */
create or replace function public.worker_blind_cow_duel_join(p_me text, p_token text, p_name text default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_me text := public.worker_blind_cow_me(p_me);
  v_duel public.worker_blind_cow_duel;
  v_slot smallint;
begin
  if v_me is null then return public.worker_blind_cow_fail('bad_identity'); end if;
  select * into v_duel from public.worker_blind_cow_duel
   where public_token_hash = public.worker_blind_cow_token_hash(p_token) for update;
  if not found then return public.worker_blind_cow_fail('not_found'); end if;
  select slot into v_slot from public.worker_blind_cow_duel_slot where duel_id = v_duel.id and anon_id = v_me;
  if found then return jsonb_build_object('ok', true, 'slot', v_slot); end if;
  if v_duel.expires_at < now() then return public.worker_blind_cow_fail('expired'); end if;
  if exists (select 1 from public.worker_blind_cow_duel_slot where duel_id = v_duel.id and slot = 2) then
    return public.worker_blind_cow_fail('full');
  end if;
  insert into public.worker_blind_cow_duel_slot (duel_id, slot, user_id, anon_id, display_name, joined_at)
  values (v_duel.id, 2, auth.uid(), v_me, nullif(left(btrim(coalesce(p_name, '')), 24), ''), now());
  update public.worker_blind_cow_duel set status = 'active' where id = v_duel.id and status = 'waiting';
  return jsonb_build_object('ok', true, 'slot', 2);
end $$;

/* פתיחת הריצה — פעם אחת. קריאה שנייה (רענון, לשונית שנייה) מחזירה את אותה ריצה ואת אותו שעון. */
create or replace function public.worker_blind_cow_run_start(p_me text, p_token text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_slot public.worker_blind_cow_duel_slot := public.worker_blind_cow_my_slot(p_me, p_token);
  v_duel public.worker_blind_cow_duel;
  v_run uuid;
begin
  if v_slot.id is null then return public.worker_blind_cow_fail('not_joined'); end if;
  select * into v_duel from public.worker_blind_cow_duel where id = v_slot.duel_id;
  if v_slot.run_id is not null then
    perform public.worker_blind_cow_settle(v_slot.run_id);
    return jsonb_build_object('ok', true) || public.worker_blind_cow_view(v_slot.run_id);
  end if;
  if v_duel.expires_at < now() then return public.worker_blind_cow_fail('expired'); end if;
  -- the row lock makes a second tab wait for the first, which then finds run_id set
  perform 1 from public.worker_blind_cow_duel_slot where id = v_slot.id for update;
  select run_id into v_run from public.worker_blind_cow_duel_slot where id = v_slot.id;
  if v_run is null then
    insert into public.worker_blind_cow_run (mode, duel_id, question_id, question_version, user_id, anon_id, scoring_version)
    values ('duel', v_duel.id, v_duel.question_id, v_duel.question_version, v_slot.user_id, v_slot.anon_id, v_duel.scoring_version)
    returning id into v_run;
    update public.worker_blind_cow_duel_slot set run_id = v_run where id = v_slot.id;
    insert into public.worker_blind_cow_run_event (run_id, kind, hint) values (v_run, 'START', 1);
  end if;
  return jsonb_build_object('ok', true) || public.worker_blind_cow_view(v_run);
end $$;

/* רמז נוסף. `p_have` הוא כמה רמזים יש למסך — לחיצה כפולה לא פותחת שניים. */
create or replace function public.worker_blind_cow_run_reveal(p_me text, p_token text, p_have integer)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_slot public.worker_blind_cow_duel_slot := public.worker_blind_cow_my_slot(p_me, p_token);
  v_run public.worker_blind_cow_run;
begin
  if v_slot.run_id is null then return public.worker_blind_cow_fail('not_started'); end if;
  perform public.worker_blind_cow_settle(v_slot.run_id);
  select * into v_run from public.worker_blind_cow_run where id = v_slot.run_id for update;
  if v_run.status = 'playing' and v_run.hints_used = p_have and v_run.hints_used < 10 then
    update public.worker_blind_cow_run set hints_used = hints_used + 1 where id = v_run.id;
    insert into public.worker_blind_cow_run_event (run_id, kind, hint) values (v_run.id, 'REVEAL_HINT', v_run.hints_used + 1);
  end if;
  return jsonb_build_object('ok', true) || public.worker_blind_cow_view(v_run.id);
end $$;

/* ניחוש — מזהה שחקן מה-Player Master, לא מחרוזת. אחרי הסיום: אותה תשובה, בלי שינוי. */
create or replace function public.worker_blind_cow_run_guess(p_me text, p_token text, p_player text, p_client_ms bigint default null)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_slot public.worker_blind_cow_duel_slot := public.worker_blind_cow_my_slot(p_me, p_token);
  v_run public.worker_blind_cow_run;
  v_target text;
  v_raw bigint;
begin
  if v_slot.run_id is null then return public.worker_blind_cow_fail('not_started'); end if;
  if p_player is null or p_player !~ '^p_[0-9a-f]{10}$' then return public.worker_blind_cow_fail('bad_player'); end if;
  perform public.worker_blind_cow_settle(v_slot.run_id);
  select * into v_run from public.worker_blind_cow_run where id = v_slot.run_id for update;
  if v_run.status = 'playing' then
    select target_player_id into v_target from public.worker_blind_cow_question
     where question_id = v_run.question_id and version = v_run.question_version;
    if p_player = v_target then
      v_raw := (extract(epoch from (now() - v_run.started_at)) * 1000)::bigint;
      update public.worker_blind_cow_run
         set status = 'solved', finished_at = now(), raw_elapsed_ms = v_raw, result_player_id = p_player,
             weighted_time_ms = public.worker_blind_cow_weighted(v_raw, v_run.hints_used, v_run.wrong_guesses, v_run.scoring_version),
             client_elapsed_ms = case when p_client_ms between 0 and 86400000 then p_client_ms end
       where id = v_run.id;
      insert into public.worker_blind_cow_run_event (run_id, kind, hint, player_id) values (v_run.id, 'SUBMIT_CORRECT', v_run.hints_used, p_player);
      perform public.worker_blind_cow_close(v_slot.duel_id);
    elsif not exists (select 1 from public.worker_blind_cow_run_event
                       where run_id = v_run.id and kind = 'SUBMIT_WRONG' and player_id = p_player) then
      -- the same wrong name twice is one mistake, not two
      update public.worker_blind_cow_run set wrong_guesses = wrong_guesses + 1 where id = v_run.id;
      insert into public.worker_blind_cow_run_event (run_id, kind, hint, player_id) values (v_run.id, 'SUBMIT_WRONG', v_run.hints_used, p_player);
    end if;
  end if;
  return jsonb_build_object('ok', true) || public.worker_blind_cow_view(v_run.id);
end $$;

/* ויתרתי. */
create or replace function public.worker_blind_cow_run_give_up(p_me text, p_token text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_slot public.worker_blind_cow_duel_slot := public.worker_blind_cow_my_slot(p_me, p_token);
begin
  if v_slot.run_id is null then return public.worker_blind_cow_fail('not_started'); end if;
  perform public.worker_blind_cow_settle(v_slot.run_id);
  update public.worker_blind_cow_run
     set status = 'gave_up', finished_at = now(),
         raw_elapsed_ms = (extract(epoch from (now() - started_at)) * 1000)::bigint
   where id = v_slot.run_id and status = 'playing';
  if found then
    insert into public.worker_blind_cow_run_event (run_id, kind) values (v_slot.run_id, 'GIVE_UP');
  end if;
  perform public.worker_blind_cow_close(v_slot.duel_id);
  return jsonb_build_object('ok', true) || public.worker_blind_cow_view(v_slot.run_id);
end $$;

/* מצב הדו-קרב. היריב: הצטרף? סיים? — והתוצאה שלו רק אחרי שהשואל עצמו סיים. */
create or replace function public.worker_blind_cow_duel_state(p_me text, p_token text)
returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  v_me text := public.worker_blind_cow_me(p_me);
  v_duel public.worker_blind_cow_duel;
  v_mine public.worker_blind_cow_duel_slot;
  v_other public.worker_blind_cow_duel_slot;
  v_my_run public.worker_blind_cow_run;
  v_other_run public.worker_blind_cow_run;
  v_done boolean;
  v_winner text;
begin
  select * into v_duel from public.worker_blind_cow_duel where public_token_hash = public.worker_blind_cow_token_hash(p_token);
  if not found then return public.worker_blind_cow_fail('not_found'); end if;
  for v_mine in select * from public.worker_blind_cow_duel_slot where duel_id = v_duel.id and run_id is not null loop
    perform public.worker_blind_cow_settle(v_mine.run_id);
  end loop;
  perform public.worker_blind_cow_close(v_duel.id);
  select * into v_duel from public.worker_blind_cow_duel where id = v_duel.id;
  select * into v_mine from public.worker_blind_cow_duel_slot where duel_id = v_duel.id and anon_id = v_me;
  select * into v_other from public.worker_blind_cow_duel_slot where duel_id = v_duel.id and anon_id is distinct from v_me
   order by slot limit 1;
  if v_mine.run_id is not null then select * into v_my_run from public.worker_blind_cow_run where id = v_mine.run_id; end if;
  if v_other.run_id is not null then select * into v_other_run from public.worker_blind_cow_run where id = v_other.run_id; end if;
  v_done := v_my_run.id is not null and v_my_run.status <> 'playing';
  if v_done and v_other_run.id is not null and v_other_run.status <> 'playing' then
    v_winner := case
      when v_my_run.status = 'solved' and v_other_run.status <> 'solved' then 'me'
      when v_other_run.status = 'solved' and v_my_run.status <> 'solved' then 'them'
      when v_my_run.status <> 'solved' and v_other_run.status <> 'solved' then 'none'
      when v_my_run.weighted_time_ms = v_other_run.weighted_time_ms then 'tie'
      when v_my_run.weighted_time_ms < v_other_run.weighted_time_ms then 'me'
      else 'them' end;
  end if;
  return jsonb_build_object(
    'ok', true,
    'status', case when v_duel.status <> 'completed' and v_duel.expires_at < now() then 'expired' else v_duel.status end,
    'expiresAt', (extract(epoch from v_duel.expires_at) * 1000)::bigint,
    'scoringVersion', v_duel.scoring_version,
    'joined', v_mine.id is not null,
    'mySlot', v_mine.slot,
    'myName', v_mine.display_name,
    'me', case when v_mine.run_id is not null then public.worker_blind_cow_view(v_mine.run_id) end,
    'opponent', case when v_other.id is null then null else jsonb_build_object(
      'name', v_other.display_name,
      'started', v_other.run_id is not null,
      'finished', v_other_run.id is not null and v_other_run.status <> 'playing',
      -- §10: hidden until the asker has finished his own run
      'result', case when v_done and v_other_run.id is not null and v_other_run.status <> 'playing' then jsonb_build_object(
        'status', v_other_run.status,
        'hintsUsed', v_other_run.hints_used,
        'wrongGuesses', v_other_run.wrong_guesses,
        'rawElapsedMs', v_other_run.raw_elapsed_ms,
        'weightedTimeMs', v_other_run.weighted_time_ms) end) end,
    'winner', v_winner
  );
end $$;

-- =====================================================================
-- 5. RLS והרשאות — הטבלאות סגורות לגמרי; רק שבע הפעולות פתוחות
-- =====================================================================
do $rls$
declare v_table text;
begin
  foreach v_table in array array[
    'worker_blind_cow_question', 'worker_blind_cow_scoring', 'worker_blind_cow_duel',
    'worker_blind_cow_run', 'worker_blind_cow_duel_slot', 'worker_blind_cow_run_event'] loop
    execute format('alter table public.%I enable row level security', v_table);
    execute format('revoke all on public.%I from public, anon, authenticated', v_table);
  end loop;
end
$rls$;

do $sequences$
declare v_seq text;
begin
  for v_seq in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
                where n.nspname = 'public' and c.relkind = 'S' and c.relname like 'worker\_blind\_cow\_%' loop
    execute format('revoke all on sequence public.%I from public, anon, authenticated', v_seq);
  end loop;
end
$sequences$;

do $functions$
declare
  v_fn record;
  v_open text[] := array['worker_blind_cow_duel_create', 'worker_blind_cow_duel_join', 'worker_blind_cow_run_start',
                         'worker_blind_cow_run_reveal', 'worker_blind_cow_run_guess', 'worker_blind_cow_run_give_up',
                         'worker_blind_cow_duel_state'];
begin
  for v_fn in
    select p.oid::regprocedure::text as sig, p.proname
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname like 'worker\_blind\_cow\_%'
  loop
    execute format('revoke all on function %s from public, anon, authenticated', v_fn.sig);
    if v_fn.proname = any(v_open) then
      execute format('grant execute on function %s to anon, authenticated', v_fn.sig);
    end if;
  end loop;
end
$functions$;

